mapper.select:
select t.device_no as deviceNo, t.device_name as deviceName, t.oper_person as operPerson, t.oper_time as operTime, t.oper_detail as operDetail from t_device_log t
t.del_flag = 'N'
and t.device_no = #{queryDTO.deviceNo}
and t.device_name like concat('%',#{queryDTO.deviceName},'%')
and t.oper_person = #{queryDTO.operPerson}
order by oper_time desc
